    return h && isRefHeading(h[2]);
  });

  const referenceOnly =
    SCAN_MODE === "auto" && hasRefHeading;

  const groups = new Map();
  const candidates = new Map();

  const addCandidate = (
    value, label, heading, type, inReferences
  ) => {
    value = value.trim();
    if (!value) return;

    const key = identity(value);
    const old = candidates.get(key);

    if (old) {
      // 相同 URL 優先保留 [名稱](URL)
      if (
        isMarkdownUrl(value) &&
        !isMarkdownUrl(old.value)
      ) {
        old.value = value;
        old.label = label;
      }

      old.inReferences ||= inReferences;
      return;
    }

    const item = {
      key, value, label, heading, type, inReferences
    };

    candidates.set(key, item);

    if (!groups.has(heading)) {
      groups.set(heading, []);
    }

    groups.get(heading).push(item);
  };

  let heading = "未分類";
  let refLevel = null;
  let fenceChar = null;
  let fenceLength = 0;

  const markdownUrlRegex =
    /(!?)\[([^\]\n]+)\]\((https?:\/\/[^\s)]+)\)/g;

  for (const raw of lines) {
    const fence = raw.match(
      /^\s{0,3}(`{3,}|~{3,})/
    );

    if (fence) {
      const token = fence[1];

      if (!fenceChar) {
        fenceChar = token[0];
        fenceLength = token.length;
      } else if (
        token[0] === fenceChar &&
        token.length >= fenceLength
      ) {
        fenceChar = null;
        fenceLength = 0;
      }

      continue;
    }

    if (fenceChar) continue;

    const h = raw.match(
      /^\s{0,3}(#{1,6})\s+(.+?)\s*#*\s*$/
    );

    if (h) {
      const level = h[1].length;
      heading = h[2].trim();

      if (isRefHeading(heading)) {
        refLevel = level;
      } else if (
        refLevel !== null &&
        level <= refLevel
      ) {
        refLevel = null;
      }

      continue;
    }

    if (referenceOnly && refLevel === null) {
      continue;
    }

    const line = raw.replace(/`+[^`\n]*`+/g, "");

    const groupName =
      /^\s*\[\^[^\]]+\]:/.test(line)
        ? "註腳來源"
        : heading;

    const inReferences = refLevel !== null;

    // ===== Wikilink =====

    for (const m of line.matchAll(
      /(!?)\[\[([^\]\n]+)\]\]/g
    )) {
      if (m[1]) continue;

      const [target, alias] = m[2].split(
        /\|(.+)/, 2
      );

      if (target.trim()) {
        addCandidate(
          `[[${target.trim()}]]`,
          alias?.trim() || target.trim(),
          groupName,
          "wiki",
          inReferences
        );
      }
    }

    // ===== Markdown URL =====
    // 保留完整 [名稱](URL)

    for (const m of line.matchAll(markdownUrlRegex)) {
      if (m[1]) continue;

      addCandidate(
        m[0],
        m[2],
        groupName,
        "url",
        inReferences
      );
    }

    // ===== 純文字 URL =====
    // 排除已擷取的 Markdown 連結

    const plainLine = line.replace(
      markdownUrlRegex, " "
    );

    for (const m of plainLine.matchAll(
      /https?:\/\/[^\s<>\])]+/g
    )) {
      const url = m[0].replace(
        /[.,;!?，。；]+$/, ""
      );

      addCandidate(
        url,
        url,
        groupName,
        "url",
        inReferences
      );
    }
  }

  // ===== 既有 references =====

  const fm = app.metadataCache
    .getFileCache(file)?.frontmatter;

  const rawReferences = fm?.[PROPERTY];

  const existing = (
    Array.isArray(rawReferences)
      ? rawReferences
      : rawReferences
        ? [rawReferences]
        : []
  )
    .map(String)
    .map((v) => v.trim())
    .filter(Boolean);

  for (const value of existing) {
    const key = identity(value);

    if (!candidates.has(key)) {
      addCandidate(
        value,
        value,
        "原有 references（本文未找到）",
        "existing",
        false
      );
    } else if (
      isMarkdownUrl(value) &&
      !isMarkdownUrl(candidates.get(key).value)
    ) {
      const item = candidates.get(key);
      item.value = value;
      item.label = value.match(
        /^\[([^\]]+)\]/
      )[1];
    }
  }

  const selected = new Set(existing.map(identity));
  const manual = new Map();

  const allFiles = app.vault
    .getFiles()
    .filter((f) => f.path !== file.path);

  const toWiki = (target) =>
    `[[${app.metadataCache.fileToLinktext(
      target, file.path, true
    )}]]`;

  // ===== Modal =====

  const modal = new Modal(app);
  modal.setTitle("管理 references");

  modal.contentEl.createEl("p", {
    text: referenceOnly
      ? "已掃描參考資料章節；也可以手動加入網址或 Vault 檔案。"
      : "已掃描全文；也可以手動加入網址或 Vault 檔案。"
  });

  const tools = modal.contentEl.createDiv({
    cls: "modal-button-container"
  });

  const recommend = tools.createEl("button", {
    text: "勾選建議來源"
  });

  const clear = tools.createEl("button", {
    text: "取消全部勾選"
  });

  const counter = modal.contentEl.createEl("p");
  counter.style.color = "var(--text-muted)";

  const toggleMap = new Map();

  const updateCount = () => {
    counter.setText(
      `已勾選 ${selected.size + manual.size} 項`
    );
  };

  const refresh = () => {
    for (const [key, toggle] of toggleMap) {
      toggle.setValue(selected.has(key));
    }
    updateCount();
  };

  recommend.onclick = () => {
    for (const item of candidates.values()) {
      const attachment =
        /\.(pdf|png|jpe?g|gif|webp|svg|zip)(?:[#?\]]|$)/i
          .test(item.value);

      const tool =
        /(工具|檢測|下載|tools?)/i
          .test(item.heading);

      const sourceNote =
        item.type === "wiki" &&
        /^\[\[(CLIP｜|NOTE｜)/.test(item.value);

      if (
        item.inReferences &&
        !attachment &&
        !tool &&
        (item.type === "url" || sourceNote)
      ) {
        selected.add(item.key);
      }
    }

    refresh();
  };

  // ===== 掃描來源清單 =====

  const foundList = modal.contentEl.createDiv();

  Object.assign(foundList.style, {
    maxHeight: "36vh",
    overflowY: "auto",
    paddingRight: "6px"
  });

  for (const [name, items] of groups) {
    // Heading 獨立一行
    foundList.createEl("h4", { text: name });

    for (const item of items) {
      new Setting(foundList)
        .setName(item.label)
        .setDesc(item.value)
        .addToggle((toggle) => {
          toggleMap.set(item.key, toggle);
          toggle.setValue(
            selected.has(item.key)
          );

          toggle.onChange((on) => {
            if (on) {
              selected.add(item.key);
            } else {
              selected.delete(item.key);
            }
            updateCount();
          });
        });
    }
  }

  if (!candidates.size) {
    foundList.createEl("p", {
      text: "沒有掃描到連結，可以手動新增。"
    });
  }

  // ===== 手動新增 =====

  const section = modal.contentEl.createDiv();
  section.style.marginTop = "14px";

  const header = section.createDiv();

  Object.assign(header.style, {
    display: "flex",
    alignItems: "center",
    justifyContent: "space-between"
  });

  header.createEl("h4", { text: "手動新增" });

  const plus = header.createEl("button", {
    text: "+"
  });

  plus.title = "搜尋 Vault 檔案或貼上網址";

  const manualList = section.createDiv();
  const inputArea = section.createDiv();

  Object.assign(inputArea.style, {
    position: "relative",
    marginTop: "8px"
  });

  const inputRow = inputArea.createDiv();

  Object.assign(inputRow.style, {
    display: "flex",
    alignItems: "center",
    gap: "8px"
  });

  const input = inputRow.createEl("input");
  input.type = "text";
  input.placeholder =
    "搜尋 Vault 檔案或貼上 [名稱](網址)…";

  Object.assign(input.style, {
    flex: "1",
    minWidth: "0"
  });

  const addButton = inputRow.createEl("button", {
    text: "加入"
  });

  const dropdown = inputArea.createDiv();

  Object.assign(dropdown.style, {
    display: "none",
    position: "absolute",
    bottom: "100%",
    left: "0",
    right: "0",
    zIndex: "30",
    maxHeight: "240px",
    overflowY: "auto",
    border: "1px solid var(--background-modifier-border)",
    background: "var(--background-primary)",
    borderRadius: "8px",
    boxShadow: "var(--shadow-s)"
  });

  function renderManual() {
    manualList.empty();

    for (const [key, value] of manual) {
      const row = manualList.createDiv();

      Object.assign(row.style, {
        display: "flex",
        alignItems: "center",
        justifyContent: "space-between",
        gap: "12px",
        padding: "10px 2px",
        borderBottom:
          "1px solid var(--background-modifier-border)"
      });

      const label = row.createDiv();

      Object.assign(label.style, {
        minWidth: "0",
        overflowWrap: "anywhere"
      });

      const display = isMarkdownUrl(value)
        ? value.match(/^\[([^\]]+)\]/)[1]
        : value.startsWith("[[")
          ? value.slice(2, -2)
              .split("|")[0]
              .split("/").pop()
          : value;

      label.createEl("div", { text: display });

      if (display !== value) {
        const detail = label.createEl("small", {
          text: value
        });
        detail.style.color = "var(--text-muted)";
      }

      const remove = row.createEl("button", {
        text: "×"
      });

      remove.title = "移除此項";

      remove.onclick = () => {
        manual.delete(key);
        renderManual();
        updateCount();
      };
    }
  }

  clear.onclick = () => {
    selected.clear();
    manual.clear();
    renderManual();
    refresh();
  };

  // ===== Vault Autocomplete =====

  const getMatches = (text) => {
    const q = text
      .toLowerCase()
      .replace(/^\[\[/, "")
      .replace(/\]\]$/, "")
      .trim();

    if (
      !q ||
      /^https?:\/\//.test(q) ||
      isMarkdownUrl(text)
    ) {
      return [];
    }

    return allFiles
      .map((f) => {
        const base = f.basename.toLowerCase();
        const name = f.name.toLowerCase();
        const path = f.path.toLowerCase();

        const score =
          base === q || name === q || path === q
            ? 0
            : base.startsWith(q) ? 1
            : name.startsWith(q) ? 2
            : base.includes(q) ? 3
            : path.includes(q) ? 4
            : 99;

        return { f, score };
      })
      .filter((x) => x.score < 99)
      .sort(
        (a, b) =>
          a.score - b.score ||
          a.f.path.localeCompare(b.f.path)
      )
      .slice(0, MAX_SUGGESTIONS)
      .map((x) => x.f);
  };

  let matches = [];
  let active = 0;

  const hideDropdown = () => {
    dropdown.style.display = "none";
  };

  const addValue = (text) => {
    const value = text.trim();
    if (!value) return;

    const key = identity(value);

    if (candidates.has(key)) {
      const item = candidates.get(key);

      if (
        isMarkdownUrl(value) &&
        !isMarkdownUrl(item.value)
      ) {
        item.value = value;
      }

      selected.add(key);
      refresh();

      new Notice(
        "來源已在上方清單中，已勾選"
      );
    } else if (!manual.has(key)) {
      manual.set(key, value);
      renderManual();
      updateCount();
    } else {
      // 相同 URL 可改用新的 Markdown 名稱
      if (isMarkdownUrl(value)) {
        manual.set(key, value);
      }

      renderManual();
    }

    input.value = "";
    matches = [];
    hideDropdown();
    input.focus();
  };

  const renderSuggestions = () => {
    dropdown.empty();

    if (!matches.length) {
      hideDropdown();
      return;
    }

    dropdown.style.display = "block";

    matches.forEach((target, i) => {
      const option = dropdown.createEl("button");
      option.type = "button";

      Object.assign(option.style, {
        display: "block",
        width: "100%",
        textAlign: "left",
        height: "auto",
        padding: "8px 12px",
        whiteSpace: "normal",
        border: "none",
        borderRadius: "0",
        boxShadow: "none",
        background:
          i === active
            ? "var(--background-modifier-hover)"
            : "transparent"
      });

      option.createEl("div", {
        text: target.name
      });

      const path = option.createEl("small", {
        text: target.path
      });

      path.style.color = "var(--text-muted)";

      option.addEventListener("mouseenter", () => {
        active = i;

        for (const [index, element] of
          [...dropdown.children].entries()) {
          element.style.background =
            index === active
              ? "var(--background-modifier-hover)"
              : "transparent";
        }
      });

      option.addEventListener("mousedown", (event) => {
        event.preventDefault();
        addValue(toWiki(target));
      });
    });
  };

  const updateSuggestions = () => {
    matches = getMatches(input.value);
    active = 0;
    renderSuggestions();
  };

  input.addEventListener("input", updateSuggestions);
  input.addEventListener("blur", hideDropdown);

  plus.onclick = () => {
    input.focus();
    updateSuggestions();
  };

  // ===== 輸入提交 =====

  const submitInput = () => {
    const text = input.value.trim();
    if (!text) return;

    // 保留完整 Markdown 連結
    if (
      isMarkdownUrl(text) ||
      /^https?:\/\/\S+$/.test(text) ||
      /^\[\[[^\]\n]+\]\]$/.test(text)
    ) {
      addValue(text);
    } else if (matches.length) {
      addValue(toWiki(matches[active]));
    } else {
      new Notice(
        "請選擇 Vault 檔案，或輸入 URL / [名稱](URL) / [[連結]]"
      );
    }
  };

  addButton.onclick = submitInput;

  input.addEventListener("keydown", (event) => {
    if (
      event.key === "ArrowDown" &&
      matches.length
    ) {
      event.preventDefault();
      active = (active + 1) % matches.length;
      renderSuggestions();
    } else if (
      event.key === "ArrowUp" &&
      matches.length
    ) {
      event.preventDefault();
      active =
        (active + matches.length - 1) %
        matches.length;
      renderSuggestions();
    } else if (event.key === "Enter") {
      event.preventDefault();
      submitInput();
    } else if (
      event.key === "Escape" &&
      dropdown.style.display !== "none"
    ) {
      event.preventDefault();
      event.stopPropagation();
      matches = [];
      hideDropdown();
    }
  });

  // ===== 儲存 =====

  const footer = modal.contentEl.createDiv({
    cls: "modal-button-container"
  });

  footer.createEl("button", {
    text: "取消"
  }).onclick = () => modal.close();

  const save = footer.createEl("button", {
    text: "更新 references",
    cls: "mod-cta"
  });

  save.onclick = async () => {
    save.disabled = true;

    try {
      const values = [
        ...[...selected]
          .map((key) => candidates.get(key)?.value)
          .filter(Boolean),
        ...manual.values()
      ];

      await app.fileManager.processFrontMatter(
        file,
        (frontmatter) => {
          frontmatter[PROPERTY] = values;
        }
      );

      modal.close();

      new Notice(
        `references 已更新（${values.length} 筆）`
      );
    } catch (error) {
      console.error("Manage References", error);
      new Notice("更新失敗，請查看開發者主控台");
      save.disabled = false;
    }
  };

  renderManual();
  updateCount();
  modal.open();
})();

/*
 * Note Toolbar — Manage References v2.1
 * 保留 Markdown 連結名稱、避免重複網址、
 * Vault Autocomplete、Heading 分組
 */
(async () => {
  const app = ntb.app;
  const { Modal, Setting, Notice } = ntb.o;
  const file = app.workspace.getActiveFile();

  const SCAN_MODE = "auto"; // "auto" | "all"
  const PROPERTY = "references";
  const MAX_SUGGESTIONS = 8;

  if (!file || file.extension !== "md") {
    new Notice("請先開啟 Markdown 筆記");
    return;
  }

  // ===== 連結識別 =====

  const isMarkdownUrl = (value) =>
    /^\[[^\]\n]+\]\(https?:\/\/[^\s)]+\)$/.test(value);

  // 裸網址與 Markdown 連結使用相同的識別 Key
  const identity = (value) => {
    const md = value.match(
      /^\[[^\]\n]+\]\((https?:\/\/[^\s)]+)\)$/
    );
    if (md) return `url:${md[1]}`;

    if (/^https?:\/\/\S+$/.test(value)) {
      return `url:${value}`;
    }

    const wiki = value.match(/^\[\[([^\]\n]+)\]\]$/);
    if (wiki) {
      return `wiki:${wiki[1].split("|")[0].trim()}`;
    }

    return `text:${value}`;
  };

  const isRefHeading = (title) => {
    const name = title
      .replace(/^\s*\d+\s*[｜|.、:：-]\s*/, "")
      .replace(/\s+#+\s*$/, "")
      .trim()
      .toLowerCase();

    return /^(參考資料|參考文獻|參考文件|參考連結|資料來源|來源與參考|引用資料|延伸閱讀|相關連結|references?|sources?|bibliography|further reading)$/.test(name);
  };

  // ===== 掃描筆記 =====

  const markdown = await app.vault.cachedRead(file);
  const body = markdown.replace(
    /^---[ \t]*\r?\n[\s\S]*?\r?\n---[ \t]*(?:\r?\n|$)/,
    ""
  );
  const lines = body.split(/\r?\n/);

  const hasRefHeading = lines.some((line) => {
    const h = line.match(/^\s{0,3}(#{1,6})\s+(.+)$/);
    return h && isRefHeading(h[2]);
  });

  const referenceOnly =
    SCAN_MODE === "auto" && hasRefHeading;

  const groups = new Map();
  const candidates = new Map();

  const addCandidate = (
    value, label, heading, type, inReferences
  ) => {
    value = value.trim();
    if (!value) return;

    const key = identity(value);
    const old = candidates.get(key);

    if (old) {
      // 相同 URL 優先保留 [名稱](URL)
      if (
        isMarkdownUrl(value) &&
        !isMarkdownUrl(old.value)
      ) {
        old.value = value;
        old.label = label;
      }

      old.inReferences ||= inReferences;
      return;
    }

    const item = {
      key, value, label, heading, type, inReferences
    };

    candidates.set(key, item);

    if (!groups.has(heading)) {
      groups.set(heading, []);
    }

    groups.get(heading).push(item);
  };

  let heading = "未分類";
  let refLevel = null;
  let fenceChar = null;
  let fenceLength = 0;

  const markdownUrlRegex =
    /(!?)\[([^\]\n]+)\]\((https?:\/\/[^\s)]+)\)/g;

  for (const raw of lines) {
    const fence = raw.match(
      /^\s{0,3}(`{3,}|~{3,})/
    );

    if (fence) {
      const token = fence[1];

      if (!fenceChar) {
        fenceChar = token[0];
        fenceLength = token.length;
      } else if (
        token[0] === fenceChar &&
        token.length >= fenceLength
      ) {
        fenceChar = null;
        fenceLength = 0;
      }

      continue;
    }

    if (fenceChar) continue;

    const h = raw.match(
      /^\s{0,3}(#{1,6})\s+(.+?)\s*#*\s*$/
    );

    if (h) {
      const level = h[1].length;
      heading = h[2].trim();

      if (isRefHeading(heading)) {
        refLevel = level;
      } else if (
        refLevel !== null &&
        level <= refLevel
      ) {
        refLevel = null;
      }

      continue;
    }

    if (referenceOnly && refLevel === null) {
      continue;
    }

    const line = raw.replace(/`+[^`\n]*`+/g, "");

    const groupName =
      /^\s*\[\^[^\]]+\]:/.test(line)
        ? "註腳來源"
        : heading;

    const inReferences = refLevel !== null;

    // ===== Wikilink =====

    for (const m of line.matchAll(
      /(!?)\[\[([^\]\n]+)\]\]/g
    )) {
      if (m[1]) continue;

      const [target, alias] = m[2].split(
        /\|(.+)/, 2
      );

      if (target.trim()) {
        addCandidate(
          `[[${target.trim()}]]`,
          alias?.trim() || target.trim(),
          groupName,
          "wiki",
          inReferences
        );
      }
    }

    // ===== Markdown URL =====
    // 保留完整 [名稱](URL)

    for (const m of line.matchAll(markdownUrlRegex)) {
      if (m[1]) continue;

      addCandidate(
        m[0],
        m[2],
        groupName,
        "url",
        inReferences
      );
    }

    // ===== 純文字 URL =====
    // 排除已擷取的 Markdown 連結

    const plainLine = line.replace(
      markdownUrlRegex, " "
    );

    for (const m of plainLine.matchAll(
      /https?:\/\/[^\s<>\])]+/g
    )) {
      const url = m[0].replace(
        /[.,;!?，。；]+$/, ""
      );

      addCandidate(
        url,
        url,
        groupName,
        "url",
        inReferences
      );
    }
  }

  // ===== 既有 references =====

  const fm = app.metadataCache
    .getFileCache(file)?.frontmatter;

  const rawReferences = fm?.[PROPERTY];

  const existing = (
    Array.isArray(rawReferences)
      ? rawReferences
      : rawReferences
        ? [rawReferences]
        : []
  )
    .map(String)
    .map((v) => v.trim())
    .filter(Boolean);

  for (const value of existing) {
    const key = identity(value);

    if (!candidates.has(key)) {
      addCandidate(
        value,
        value,
        "原有 references（本文未找到）",
        "existing",
        false
      );
    } else if (
      isMarkdownUrl(value) &&
      !isMarkdownUrl(candidates.get(key).value)
    ) {
      const item = candidates.get(key);
      item.value = value;
      item.label = value.match(
        /^\[([^\]]+)\]/
      )[1];
    }
  }

  const selected = new Set(existing.map(identity));
  const manual = new Map();

  const allFiles = app.vault
    .getFiles()
    .filter((f) => f.path !== file.path);

  const toWiki = (target) =>
    `[[${app.metadataCache.fileToLinktext(
      target, file.path, true
    )}]]`;

  // ===== Modal =====

  const modal = new Modal(app);
  modal.setTitle("管理 references");

  modal.contentEl.createEl("p", {
    text: referenceOnly
      ? "已掃描參考資料章節；也可以手動加入網址或 Vault 檔案。"
      : "已掃描全文；也可以手動加入網址或 Vault 檔案。"
  });

  const tools = modal.contentEl.createDiv({
    cls: "modal-button-container"
  });

  const recommend = tools.createEl("button", {
    text: "勾選建議來源"
  });

  const clear = tools.createEl("button", {
    text: "取消全部勾選"
  });

  const counter = modal.contentEl.createEl("p");
  counter.style.color = "var(--text-muted)";

  const toggleMap = new Map();

  const updateCount = () => {
    counter.setText(
      `已勾選 ${selected.size + manual.size} 項`
    );
  };

  const refresh = () => {
    for (const [key, toggle] of toggleMap) {
      toggle.setValue(selected.has(key));
    }
    updateCount();
  };

  recommend.onclick = () => {
    for (const item of candidates.values()) {
      const attachment =
        /\.(pdf|png|jpe?g|gif|webp|svg|zip)(?:[#?\]]|$)/i
          .test(item.value);

      const tool =
        /(工具|檢測|下載|tools?)/i
          .test(item.heading);

      const sourceNote =
        item.type === "wiki" &&
        /^\[\[(CLIP｜|NOTE｜)/.test(item.value);

      if (
        item.inReferences &&
        !attachment &&
        !tool &&
        (item.type === "url" || sourceNote)
      ) {
        selected.add(item.key);
      }
    }

    refresh();
  };

  // ===== 掃描來源清單 =====

  const foundList = modal.contentEl.createDiv();

  Object.assign(foundList.style, {
    maxHeight: "36vh",
    overflowY: "auto",
    paddingRight: "6px"
  });

  for (const [name, items] of groups) {
    // Heading 獨立一行
    foundList.createEl("h4", { text: name });

    for (const item of items) {
      new Setting(foundList)
        .setName(item.label)
        .setDesc(item.value)
        .addToggle((toggle) => {
          toggleMap.set(item.key, toggle);
          toggle.setValue(
            selected.has(item.key)
          );

          toggle.onChange((on) => {
            if (on) {
              selected.add(item.key);
            } else {
              selected.delete(item.key);
            }
            updateCount();
          });
        });
    }
  }

  if (!candidates.size) {
    foundList.createEl("p", {
      text: "沒有掃描到連結，可以手動新增。"
    });
  }

  // ===== 手動新增 =====

  const section = modal.contentEl.createDiv();
  section.style.marginTop = "14px";

  const header = section.createDiv();

  Object.assign(header.style, {
    display: "flex",
    alignItems: "center",
    justifyContent: "space-between"
  });

  header.createEl("h4", { text: "手動新增" });

  const plus = header.createEl("button", {
    text: "+"
  });

  plus.title = "搜尋 Vault 檔案或貼上網址";

  const manualList = section.createDiv();
  const inputArea = section.createDiv();

  Object.assign(inputArea.style, {
    position: "relative",
    marginTop: "8px"
  });

  const inputRow = inputArea.createDiv();

  Object.assign(inputRow.style, {
    display: "flex",
    alignItems: "center",
    gap: "8px"
  });

  const input = inputRow.createEl("input");
  input.type = "text";
  input.placeholder =
    "搜尋 Vault 檔案或貼上 [名稱](網址)…";

  Object.assign(input.style, {
    flex: "1",
    minWidth: "0"
  });

  const addButton = inputRow.createEl("button", {
    text: "加入"
  });

  const dropdown = inputArea.createDiv();

  Object.assign(dropdown.style, {
    display: "none",
    position: "absolute",
    bottom: "100%",
    left: "0",
    right: "0",
    zIndex: "30",
    maxHeight: "240px",
    overflowY: "auto",
    border: "1px solid var(--background-modifier-border)",
    background: "var(--background-primary)",
    borderRadius: "8px",
    boxShadow: "var(--shadow-s)"
  });

  function renderManual() {
    manualList.empty();

    for (const [key, value] of manual) {
      const row = manualList.createDiv();

      Object.assign(row.style, {
        display: "flex",
        alignItems: "center",
        justifyContent: "space-between",
        gap: "12px",
        padding: "10px 2px",
        borderBottom:
          "1px solid var(--background-modifier-border)"
      });

      const label = row.createDiv();

      Object.assign(label.style, {
        minWidth: "0",
        overflowWrap: "anywhere"
      });

      const display = isMarkdownUrl(value)
        ? value.match(/^\[([^\]]+)\]/)[1]
        : value.startsWith("[[")
          ? value.slice(2, -2)
              .split("|")[0]
              .split("/").pop()
          : value;

      label.createEl("div", { text: display });

      if (display !== value) {
        const detail = label.createEl("small", {
          text: value
        });
        detail.style.color = "var(--text-muted)";
      }

      const remove = row.createEl("button", {
        text: "×"
      });

      remove.title = "移除此項";

      remove.onclick = () => {
        manual.delete(key);
        renderManual();
        updateCount();
      };
    }
  }

  clear.onclick = () => {
    selected.clear();
    manual.clear();
    renderManual();
    refresh();
  };

  // ===== Vault Autocomplete =====

  const getMatches = (text) => {
    const q = text
      .toLowerCase()
      .replace(/^\[\[/, "")
      .replace(/\]\]$/, "")
      .trim();

    if (
      !q ||
      /^https?:\/\//.test(q) ||
      isMarkdownUrl(text)
    ) {
      return [];
    }

    return allFiles
      .map((f) => {
        const base = f.basename.toLowerCase();
        const name = f.name.toLowerCase();
        const path = f.path.toLowerCase();

        const score =
          base === q || name === q || path === q
            ? 0
            : base.startsWith(q) ? 1
            : name.startsWith(q) ? 2
            : base.includes(q) ? 3
            : path.includes(q) ? 4
            : 99;

        return { f, score };
      })
      .filter((x) => x.score < 99)
      .sort(
        (a, b) =>
          a.score - b.score ||
          a.f.path.localeCompare(b.f.path)
      )
      .slice(0, MAX_SUGGESTIONS)
      .map((x) => x.f);
  };

  let matches = [];
  let active = 0;

  const hideDropdown = () => {
    dropdown.style.display = "none";
  };

  const addValue = (text) => {
    const value = text.trim();
    if (!value) return;

    const key = identity(value);

    if (candidates.has(key)) {
      const item = candidates.get(key);

      if (
        isMarkdownUrl(value) &&
        !isMarkdownUrl(item.value)
      ) {
        item.value = value;
      }

      selected.add(key);
      refresh();

      new Notice(
        "來源已在上方清單中，已勾選"
      );
    } else if (!manual.has(key)) {
      manual.set(key, value);
      renderManual();
      updateCount();
    } else {
      // 相同 URL 可改用新的 Markdown 名稱
      if (isMarkdownUrl(value)) {
        manual.set(key, value);
      }

      renderManual();
    }

    input.value = "";
    matches = [];
    hideDropdown();
    input.focus();
  };

  const renderSuggestions = () => {
    dropdown.empty();

    if (!matches.length) {
      hideDropdown();
      return;
    }

    dropdown.style.display = "block";

    matches.forEach((target, i) => {
      const option = dropdown.createEl("button");
      option.type = "button";

      Object.assign(option.style, {
        display: "block",
        width: "100%",
        textAlign: "left",
        height: "auto",
        padding: "8px 12px",
        whiteSpace: "normal",
        border: "none",
        borderRadius: "0",
        boxShadow: "none",
        background:
          i === active
            ? "var(--background-modifier-hover)"
            : "transparent"
      });

      option.createEl("div", {
        text: target.name
      });

      const path = option.createEl("small", {
        text: target.path
      });

      path.style.color = "var(--text-muted)";

      option.addEventListener("mouseenter", () => {
        active = i;

        for (const [index, element] of
          [...dropdown.children].entries()) {
          element.style.background =
            index === active
              ? "var(--background-modifier-hover)"
              : "transparent";
        }
      });

      option.addEventListener("mousedown", (event) => {
        event.preventDefault();
        addValue(toWiki(target));
      });
    });
  };

  const updateSuggestions = () => {
    matches = getMatches(input.value);
    active = 0;
    renderSuggestions();
  };

  input.addEventListener("input", updateSuggestions);
  input.addEventListener("blur", hideDropdown);

  plus.onclick = () => {
    input.focus();
    updateSuggestions();
  };

  // ===== 輸入提交 =====

  const submitInput = () => {
    const text = input.value.trim();
    if (!text) return;

    // 保留完整 Markdown 連結
    if (
      isMarkdownUrl(text) ||
      /^https?:\/\/\S+$/.test(text) ||
      /^\[\[[^\]\n]+\]\]$/.test(text)
    ) {
      addValue(text);
    } else if (matches.length) {
      addValue(toWiki(matches[active]));
    } else {
      new Notice(
        "請選擇 Vault 檔案，或輸入 URL / [名稱](URL) / [[連結]]"
      );
    }
  };

  addButton.onclick = submitInput;

  input.addEventListener("keydown", (event) => {
    if (
      event.key === "ArrowDown" &&
      matches.length
    ) {
      event.preventDefault();
      active = (active + 1) % matches.length;
      renderSuggestions();
    } else if (
      event.key === "ArrowUp" &&
      matches.length
    ) {
      event.preventDefault();
      active =
        (active + matches.length - 1) %
        matches.length;
      renderSuggestions();
    } else if (event.key === "Enter") {
      event.preventDefault();
      submitInput();
    } else if (
      event.key === "Escape" &&
      dropdown.style.display !== "none"
    ) {
      event.preventDefault();
      event.stopPropagation();
      matches = [];
      hideDropdown();
    }
  });

  // ===== 儲存 =====

  const footer = modal.contentEl.createDiv({
    cls: "modal-button-container"
  });

  footer.createEl("button", {
    text: "取消"
  }).onclick = () => modal.close();

  const save = footer.createEl("button", {
    text: "更新 references",
    cls: "mod-cta"
  });

  save.onclick = async () => {
    save.disabled = true;

    try {
      const values = [
        ...[...selected]
          .map((key) => candidates.get(key)?.value)
          .filter(Boolean),
        ...manual.values()
      ];

      await app.fileManager.processFrontMatter(
        file,
        (frontmatter) => {
          frontmatter[PROPERTY] = values;
        }
      );

      modal.close();

      new Notice(
        `references 已更新（${values.length} 筆）`
      );
    } catch (error) {
      console.error("Manage References", error);
      new Notice("更新失敗，請查看開發者主控台");
      save.disabled = false;
    }
  };

  renderManual();
  updateCount();
  modal.open();
})();
